void generate_chunk_data(ChunkData* data, int x, int z)
{
    {
    int heights[16][16] = {0};
    
        // Base Terrain (Rolling Hills)
        Image noise = GenImagePerlinNoise(16, 16, x * 16, z * 16, 0.05f);
        Color* pixels = LoadImageColors(noise);
        
        // Mountain Terrain (Large Scale, jagged)
        Image m_noise = GenImagePerlinNoise(16, 16, x * 16, z * 16, 0.015f);
        Color* m_pixels = LoadImageColors(m_noise);
        
        for(int i=0; i<16; i++) {
            for(int j=0; j<16; j++) {
                // pixels is row-major
                Color col = pixels[j * 16 + i];
                float base_val = (float)col.r / 255.0; // 0.0 - 1.0
                
                Color m_col = m_pixels[j * 16 + i];
                float m_val = (float)m_col.r / 255.0; // 0.0 - 1.0
                
                // Height Formula:
                // Base: 25 + noise * 15 (25..40)
                // Mountains: m_val^3 * 80 (Exponential peaks up to +80)
                
                // Height Formula Tuned (Steeper):
                // Base: 5 + noise * 50 (Range 5..55).
                // Center is ~30 (Sea Level).
                // Steeper slopes = less shallow water, more abrupt transitions.
                
                float h_f = 5.0 + (base_val * 50.0);
                
                // Mountains: m_val^2 * 90 (Squared for wider mountains, up to +90 height)
                float m_contrib = m_val * m_val; 
                h_f += m_contrib * 90.0;
                
                int h = (int)h_f;
                
                // Cap
                if (h > CHUNK_HEIGHT - 6) h = CHUNK_HEIGHT - 6; // Leave room for trees
                if (h < 2) h = 2; // Bedrock
                
                heights[i][j] = h;
            }
        }
        UnloadImageColors(pixels);
        UnloadImage(noise);
        UnloadImageColors(m_pixels);
        UnloadImage(m_noise);
    
for (ZC_AUTO cx = 0; cx < 16; cx++)     {
for (ZC_AUTO cz = 0; cz < 16; cz++)     {
    int h = heights[_z_check_bounds(cx, 16)][_z_check_bounds(cz, 16)];
for (ZC_AUTO cy = 0; cy < CHUNK_HEIGHT; cy++)     {
    int l = 0;
if ((cy < (h - 1)))     {
(data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 3);
    }
 else if ((cy < h))     {
(data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 1);
    }
 else if ((cy == h))     {
if ((h < 30))     {
(data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 9);
    }
 else     {
(data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 2);
    }
(l = 240);
    }
 else     {
(data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 0);
(l = 240);
    }
(data->light[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = l);
    }
    }
    }
    const int SEA_LEVEL = 30;
for (ZC_AUTO cx = 0; cx < 16; cx++)     {
for (ZC_AUTO cz = 0; cz < 16; cz++)     {
for (ZC_AUTO cy = 0; cy < 30; cy++)     {
if ((data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] == 0))     {
(data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 8);
    }
    }
    }
    }
(data->plant_count = 0);
    int seed = ((x * 73856093) ^ (z * 19349663));
    double forest_noise_val = 0.000000;
    
         // Using a specific offset for forest noise to de-correlate from terrain height
        Image fnoise = GenImagePerlinNoise(1, 1, x, z, 0.02f); 
        Color* fp = LoadImageColors(fnoise);
        forest_noise_val = (float)fp[0].r / 255.0; // 0.0 to 1.0
        UnloadImageColors(fp);
        UnloadImage(fnoise);
    
    int tree_chance_threshold = 1;
if ((forest_noise_val > 0.550000))     {
(tree_chance_threshold = 10);
if ((forest_noise_val > 0.700000))     {
(tree_chance_threshold = 15);
    }
    }
 else if ((forest_noise_val < 0.300000))     {
(tree_chance_threshold = 0);
    }
for (ZC_AUTO cx = 0; cx < 16; cx++)     {
for (ZC_AUTO cz = 0; cz < 16; cz++)     {
    int h = heights[_z_check_bounds(cx, 16)][_z_check_bounds(cz, 16)];
if (((data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(h, 128)][_z_check_bounds(cz, 16)] == 2) && (h < (CHUNK_HEIGHT - 20))))     {
    int r = (my_rand((&seed)) % 1000);
    int place_tree = 0;
if ((tree_chance_threshold > 0))     {
if ((r < (tree_chance_threshold * 10)))     {
(place_tree = 1);
    }
    }
 else     {
if ((r < 2))     {
(place_tree = 1);
    }
    }
if (place_tree)     {
if (((((cx > 2) && (cx < 13)) && (cz > 2)) && (cz < 13)))     {
    int th = (3 + (my_rand((&seed)) % 3));
for (ZC_AUTO i = 0; i < th; i++)     {
if ((((h + 1) + i) < CHUNK_HEIGHT))     {
(data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(((h + 1) + i), 128)][_z_check_bounds(cz, 16)] = 5);
    }
    }
    int leaves_start = ((h + th) - 2);
    int leaves_end = ((h + th) + 1);
for (ZC_AUTO ly = leaves_start; ly < leaves_end; ly++)     {
if ((ly >= CHUNK_HEIGHT))     {
continue;
    }
    int radius = 2;
if ((ly == (leaves_end - 1)))     {
(radius = 1);
    }
if ((ly == leaves_end))     {
(radius = 1);
    }
for (ZC_AUTO lx = (cx - radius); lx < ((cx + radius) + 1); lx++)     {
for (ZC_AUTO lz = (cz - radius); lz < ((cz + radius) + 1); lz++)     {
    int dx = (lx - cx);
    int dz = (lz - cz);
if ((((dx * dx) + (dz * dz)) > ((radius * radius) + 1)))     {
continue;
    }
if ((data->blocks[_z_check_bounds(lx, 16)][_z_check_bounds(ly, 128)][_z_check_bounds(lz, 16)] == 0))     {
(data->blocks[_z_check_bounds(lx, 16)][_z_check_bounds(ly, 128)][_z_check_bounds(lz, 16)] = 6);
    }
    }
    }
    }
    }
    }
 else if ((r < 30))     {
if ((data->plant_count < 64))     {
(data->plants[_z_check_bounds(data->plant_count, 64)].x = (((float)(cx)) + 0.500000));
(data->plants[_z_check_bounds(data->plant_count, 64)].y = ((float)((h + 1))));
(data->plants[_z_check_bounds(data->plant_count, 64)].z = (((float)(cz)) + 0.500000));
(data->plants[_z_check_bounds(data->plant_count, 64)].plant_type = 4);
(data->plant_count = (data->plant_count + 1));
    }
    }
    }
    }
    }
for (ZC_AUTO cx = 0; cx < 16; cx++)     {
for (ZC_AUTO cz = 0; cz < 16; cz++)     {
    int in_shadow = 0;
for (ZC_AUTO i = 0; i < CHUNK_HEIGHT; i++)     {
    int cy = ((CHUNK_HEIGHT - 1) - i);
    int blk = data->blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)];
if ((!in_shadow))     {
if (((((blk != 0) && (blk != 4)) && (blk != 8)) && (blk != 6)))     {
(data->light[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 0);
(in_shadow = 1);
    }
 else     {
(data->light[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 240);
    }
    }
 else     {
(data->light[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 0);
    }
    }
    }
    }
(data->light_calculated = 1);
    }
}

int my_rand(int* seed)
{
    {
    
        *seed = (*seed * 1103515245 + 12345) & 0x7fffffff;
        return *seed;
    
    return 0;
    }
}

int check_collision(Chunk* chunks, int num_chunks, float x, float y, float z, float w, float h)
{
    {
    int min_x = ((int)(floor((x - (w / 2.000000)))));
    int max_x = ((int)(floor((x + (w / 2.000000)))));
    int min_y = ((int)(floor(y)));
    int max_y = ((int)(floor((y + h))));
    int min_z = ((int)(floor((z - (w / 2.000000)))));
    int max_z = ((int)(floor((z + (w / 2.000000)))));
for (ZC_AUTO ix = min_x; ix < (max_x + 1); ix++)     {
for (ZC_AUTO iy = min_y; iy < (max_y + 1); iy++)     {
for (ZC_AUTO iz = min_z; iz < (max_z + 1); iz++)     {
    int block = get_block(chunks, num_chunks, ix, iy, iz);
if (((((block != 0) && (block != 4)) && (!((block >= 10) && (block <= 14)))) && (block != 8)))     {
    return 1;
    }
    }
    }
    }
    return 0;
    }
}

RaycastHit raycast(Chunk* chunks, int num_chunks, float ox, float oy, float oz, float dx, float dy, float dz, float max_dist)
{
    {
    RaycastHit r = {0};
(r.hit = 0);
    float x = ox;
    float y = oy;
    float z = oz;
    double step = 0.050000;
    double dist = 0.000000;
    int last_x = ((int)(floor(x)));
    int last_y = ((int)(floor(y)));
    int last_z = ((int)(floor(z)));
while ((dist < max_dist))     {
(x = (x + (dx * step)));
(y = (y + (dy * step)));
(z = (z + (dz * step)));
(dist = (dist + step));
    int ix = ((int)(floor(x)));
    int iy = ((int)(floor(y)));
    int iz = ((int)(floor(z)));
if ((get_block(chunks, num_chunks, ix, iy, iz) != 0))     {
(r.hit = 1);
(r.x = ix);
(r.y = iy);
(r.z = iz);
(r.face_x = 0);
(r.face_y = 0);
(r.face_z = 0);
if ((ix > last_x))     {
(r.face_x = (-1));
    }
 else if ((ix < last_x))     {
(r.face_x = 1);
    }
 else if ((iy > last_y))     {
(r.face_y = (-1));
    }
 else if ((iy < last_y))     {
(r.face_y = 1);
    }
 else if ((iz > last_z))     {
(r.face_z = (-1));
    }
 else if ((iz < last_z))     {
(r.face_z = 1);
    }
    return r;
    }
(last_x = ix);
(last_y = iy);
(last_z = iz);
    }
    return r;
    }
}

