int get_chunk_index(int cx, int cz)
{
    {
    int mx = (((cx % 31) + 31) % 31);
    int mz = (((cz % 31) + 31) % 31);
    return ((mz * 31) + mx);
    }
}

void build_grass_decorations(Chunk* c, Chunk* chunks, int num_chunks)
{
    {
    
        // Count grass blocks with air above
        int grass_count = 0;
        for (int x = 0; x < 16; x++) {
            for (int y = 0; y < CHUNK_HEIGHT - 1; y++) { // check y+1
                for (int z = 0; z < 16; z++) {
                    if (c->blocks[x][y][z] == BLOCK_GRASS) {
                        int above = c->blocks[x][y + 1][z];
                        if (above == BLOCK_AIR || above == BLOCK_WATER) {
                            grass_count++;
                        }
                    }
                }
            }
        }
        
        if (grass_count == 0) {
            c->grass_deco_built = 1;
            return;
        }
        
        // Each grass block gets 25 decorations (5x5 grid)
        // Each decoration is 2 crossed quads (4 quads total)
        // Each quad = 6 vertices
        int num_decorations = grass_count * 25;
        int vertex_count = num_decorations * 6; // 1 quad per deco, 6 verts
        
        float* vertices = (float*)malloc(vertex_count * 3 * sizeof(float));
        float* normals = (float*)malloc(vertex_count * 3 * sizeof(float));
        float* texcoords = (float*)malloc(vertex_count * 2 * sizeof(float));
        unsigned char* colors = (unsigned char*)malloc(vertex_count * 4 * sizeof(unsigned char));
        
        int v_idx = 0;
        
        // Pseudo-random helper (deterministic)
        #define PRNG(seed) ((seed * 1103515245 + 12345) & 0x7FFFFFFF)
        #define PRAND_FLOAT(seed) (((float)((seed) & 0xFFFF)) / 65535.0f)
        
        for (int x = 0; x < 16; x++) {
            for (int y = 0; y < CHUNK_HEIGHT - 1; y++) {
                for (int z = 0; z < 16; z++) {
                    if (c->blocks[x][y][z] != BLOCK_GRASS) continue;
                    
                    int above = c->blocks[x][y + 1][z];
                    if (above != BLOCK_AIR && above != BLOCK_WATER) continue;
                    
                    // Deterministic seed based on block position
                    int seed_base = (c->x * 16 + x) * 73856093 ^ (y) * 19349663 ^ (c->z * 16 + z) * 83492791;
                    
                    // Sample light from the block above
                    int light_val = c->light[x][y + 1][z];
                    int light_r = ((light_val & 0xF) * 17);        // Block Light
                    int light_g = (((light_val >> 4) & 0xF) * 17); // Sky Light
                    
                    // Generate 25 decorations per grass block (5x5 grid)
                    // This ensures even distribution across the block surface
                    for (int gx = 0; gx < 5; gx++) {
                        for (int gz = 0; gz < 5; gz++) {
                            int deco_index = gx * 5 + gz;
                            int seed = PRNG(seed_base + deco_index * 12345);
                            
                            // Grid cell center (5x5 = 0.2 wide cells)
                            float cell_center_x = (float)gx * 0.2f + 0.1f;
                            float cell_center_z = (float)gz * 0.2f + 0.1f;
                            
                            // Jitter within cell (-0.1 to +0.1)
                            float jitter_x = PRAND_FLOAT(PRNG(seed)) * 0.2f - 0.1f;
                            float jitter_z = PRAND_FLOAT(PRNG(PRNG(seed))) * 0.2f - 0.1f;
                            
                            float px = (float)x + cell_center_x + jitter_x;
                            float py = (float)(y + 1);
                            float pz = (float)z + cell_center_z + jitter_z;
                            
                            // Larger size
                            // Height 0.4 to 0.7 (Doubled from previous ~0.2-0.3)
                            float height = 0.40f + PRAND_FLOAT(PRNG(PRNG(PRNG(seed)))) * 0.3f;
                            float width = 0.04f; // Narrower blades
                            
                            // Texture coords (Use Grass Top: col 1, row 0)
                            // Atlas is 4 cols x 3 rows: 0.25 wide, 0.333 tall
                            float u_min = 0.26f;  // Slight inset to avoid bleeding
                            float v_min = 0.01f;
                            float u_max = 0.49f;
                            float v_max = 0.32f;  // Row 0 ends at 0.333
                            
                            // Single quad with random rotation
                            // 1 quad = 2 triangles = 6 vertices
                            
                            // Random rotation angle (0 to 2*PI)
                            float angle = PRAND_FLOAT(PRNG(seed + 1)) * 6.28318f;
                            float s = (float)sin(angle);
                            float c_rot = (float)cos(angle); // c is chunk*, so use c_rot
                            
                            // Half width for calculation
                            float hw = width; 
                            
                            // Rotated offsets
                            // (-hw, 0) -> (-hw*c, -hw*s)
                            // (+hw, 0) -> (+hw*c, +hw*s)
                            float x1 = -hw * c_rot;
                            float z1 = -hw * s;
                            float x2 = hw * c_rot;
                            float z2 = hw * s;
                            
                            // Triangle 1
                            vertices[v_idx * 3 + 0] = px + x1; vertices[v_idx * 3 + 1] = py; vertices[v_idx * 3 + 2] = pz + z1;
                            normals[v_idx * 3 + 0] = 0; normals[v_idx * 3 + 1] = 0; normals[v_idx * 3 + 2] = 1;
                            texcoords[v_idx * 2 + 0] = u_min; texcoords[v_idx * 2 + 1] = v_max;
                            colors[v_idx * 4 + 0] = light_r; colors[v_idx * 4 + 1] = light_g; colors[v_idx * 4 + 2] = 0; colors[v_idx * 4 + 3] = 255;
                            v_idx++;
                            
                            vertices[v_idx * 3 + 0] = px + x2; vertices[v_idx * 3 + 1] = py + height; vertices[v_idx * 3 + 2] = pz + z2;
                            normals[v_idx * 3 + 0] = 0; normals[v_idx * 3 + 1] = 0; normals[v_idx * 3 + 2] = 1;
                            texcoords[v_idx * 2 + 0] = u_max; texcoords[v_idx * 2 + 1] = v_min;
                            colors[v_idx * 4 + 0] = light_r; colors[v_idx * 4 + 1] = light_g; colors[v_idx * 4 + 2] = 100; colors[v_idx * 4 + 3] = 255;
                            v_idx++;
                            
                            vertices[v_idx * 3 + 0] = px + x1; vertices[v_idx * 3 + 1] = py + height; vertices[v_idx * 3 + 2] = pz + z1;
                            normals[v_idx * 3 + 0] = 0; normals[v_idx * 3 + 1] = 0; normals[v_idx * 3 + 2] = 1;
                            texcoords[v_idx * 2 + 0] = u_min; texcoords[v_idx * 2 + 1] = v_min;
                            colors[v_idx * 4 + 0] = light_r; colors[v_idx * 4 + 1] = light_g; colors[v_idx * 4 + 2] = 100; colors[v_idx * 4 + 3] = 255;
                            v_idx++;
                            
                            // Triangle 2
                            vertices[v_idx * 3 + 0] = px + x1; vertices[v_idx * 3 + 1] = py; vertices[v_idx * 3 + 2] = pz + z1;
                            normals[v_idx * 3 + 0] = 0; normals[v_idx * 3 + 1] = 0; normals[v_idx * 3 + 2] = 1;
                            texcoords[v_idx * 2 + 0] = u_min; texcoords[v_idx * 2 + 1] = v_max;
                            colors[v_idx * 4 + 0] = light_r; colors[v_idx * 4 + 1] = light_g; colors[v_idx * 4 + 2] = 0; colors[v_idx * 4 + 3] = 255;
                            v_idx++;
                            
                            vertices[v_idx * 3 + 0] = px + x2; vertices[v_idx * 3 + 1] = py; vertices[v_idx * 3 + 2] = pz + z2;
                            normals[v_idx * 3 + 0] = 0; normals[v_idx * 3 + 1] = 0; normals[v_idx * 3 + 2] = 1;
                            texcoords[v_idx * 2 + 0] = u_max; texcoords[v_idx * 2 + 1] = v_max;
                            colors[v_idx * 4 + 0] = light_r; colors[v_idx * 4 + 1] = light_g; colors[v_idx * 4 + 2] = 0; colors[v_idx * 4 + 3] = 255;
                            v_idx++;
                            
                            vertices[v_idx * 3 + 0] = px + x2; vertices[v_idx * 3 + 1] = py + height; vertices[v_idx * 3 + 2] = pz + z2;
                            normals[v_idx * 3 + 0] = 0; normals[v_idx * 3 + 1] = 0; normals[v_idx * 3 + 2] = 1;
                            texcoords[v_idx * 2 + 0] = u_max; texcoords[v_idx * 2 + 1] = v_min;
                            colors[v_idx * 4 + 0] = light_r; colors[v_idx * 4 + 1] = light_g; colors[v_idx * 4 + 2] = 100; colors[v_idx * 4 + 3] = 255;
                            v_idx++;
                        }
                    }
                }
            }
        }
        
        // Create mesh
        Mesh mesh = {0};
        mesh.triangleCount = vertex_count / 3;
        mesh.vertexCount = vertex_count;
        mesh.vertices = vertices;
        mesh.normals = normals;
        mesh.texcoords = texcoords;
        mesh.colors = colors;
        
        SetTraceLogLevel(LOG_WARNING);
        UploadMesh(&mesh, false);
        SetTraceLogLevel(LOG_INFO);
        
        c->grass_deco_mesh = mesh;
        c->grass_deco_model = LoadModelFromMesh(mesh);
        c->grass_deco_model.materials[0].shader = get_shader_grass();
        c->grass_deco_model.materials[0].maps[MATERIAL_MAP_DIFFUSE].texture = get_tex_atlas();
        c->grass_deco_built = 1;
    
    }
}

void draw_clouds(Camera3D camera, float time, float day_time)
{
    {
if ((cloud_mesh_built == 0))     {
    return ;
    }
    double cloud_y = 100.000000;
    double drift_speed = 4.000000;
    float offset_x = (time * drift_speed);
    double loop_dist = 600.000000;
    float cam_snap_x = (((float)(((int)((camera.position.x / loop_dist))))) * loop_dist);
    float cam_snap_z = (((float)(((int)((camera.position.z / loop_dist))))) * loop_dist);
    double local_drift = 0.000000;
    
        local_drift = fmod(offset_x, loop_dist);
    
    int c_r = 255;
    int c_g = 255;
    int c_b = 255;
    int c_a = 200;
if ((day_time < 0.166000))     {
    float t = (day_time / 0.166000);
(c_r = ((int)((255.000000 * t))));
(c_g = ((int)(((100.000000 * t) + ((155.000000 * t) * t)))));
(c_b = ((int)(((100.000000 * t) + ((155.000000 * t) * t)))));
(c_a = ((int)(((100.000000 * t) + 100.000000))));
    }
 else if ((day_time < 0.500000))     {
(c_r = 255);
(c_g = 255);
(c_b = 255);
(c_a = 200);
    }
 else if ((day_time < 0.666000))     {
    float t = ((day_time - 0.500000) / 0.166000);
(c_r = ((int)((255.000000 * (1.000000 - (t * 0.500000))))));
(c_g = ((int)(((255.000000 * (1.000000 - t)) + (100.000000 * t)))));
(c_b = ((int)((255.000000 * (1.000000 - t)))));
(c_a = ((int)((200.000000 * (1.000000 - (t * 0.500000))))));
    }
 else     {
(c_r = 10);
(c_g = 10);
(c_b = 20);
(c_a = 50);
    }
BeginMode3D(camera);
    
        rlDisableBackfaceCulling(); 
        rlDisableDepthMask(); // Don't write to depth buffer (clouds are background)
        rlSetBlendMode(BLEND_ALPHA);
        
        Material mat = LoadMaterialDefault();
        mat.maps[MATERIAL_MAP_DIFFUSE].color = (Color){c_r, c_g, c_b, c_a}; 
        
        // Draw 3x3 grid around player
        for(int x=-1; x<=1; x++) {
             for(int z=-1; z<=1; z++) {
                 float px = cam_snap_x + (float)x * loop_dist + local_drift;
                 float pz = cam_snap_z + (float)z * loop_dist;
                 
                 // Render
                 DrawMesh(mesh_clouds, mat, MatrixTranslate(px, cloud_y, pz));
             }
        }
        
        rlEnableDepthMask();
        rlEnableBackfaceCulling();
    
EndMode3D();
    }
}

void init_clouds(void)
{
    {
    
        // Generate Cloud Map
        // 100x100 grid, scaled by 6.0 = 600x600 world area
        int w = 100;
        int h = 100;
        float scale = 6.0f; // Smaller cubes (was 12.0)
        
        Image noise = GenImagePerlinNoise(w, h, 0, 0, 0.15f); // Frequency increase slightly
        Color* pixels = LoadImageColors(noise);
        
        // Count cloud cubes
        int count = 0;
        for(int i=0; i<w*h; i++) {
            if(pixels[i].r > 100) count++; // Threshold (Denser)
        }
        
        // Debug
        TraceLog(LOG_INFO, TextFormat("CLOUDS: Generated %d cloud cubes from %dx%d noise", count, w, h));
        
        // Construct Mesh manually
        mesh_clouds = (Mesh){ 0 };
        mesh_clouds.vertexCount = count * 24; // 4 verts * 6 faces
        mesh_clouds.triangleCount = count * 12; // 2 tris * 6 faces
        
        mesh_clouds.vertices = (float*)MemAlloc(mesh_clouds.vertexCount * 3 * sizeof(float));
        mesh_clouds.texcoords = (float*)MemAlloc(mesh_clouds.vertexCount * 2 * sizeof(float));
        mesh_clouds.normals = (float*)MemAlloc(mesh_clouds.vertexCount * 3 * sizeof(float));
        mesh_clouds.indices = (unsigned short*)MemAlloc(mesh_clouds.triangleCount * 3 * sizeof(unsigned short));
        
        int v_idx = 0;
        int i_idx = 0;
        int idx_offset = 0;
        
        for(int y=0; y<h; y++) {
            for(int x=0; x<w; x++) {
                if(pixels[y*w+x].r > 100) {
                    float cx = (float)(x - w/2) * scale;
                    float cz = (float)(y - h/2) * scale;
                    float cy = 0.0f; // Relative to cloud layer height
                    
                    float size = scale;
                    float height = 2.0f; // Flatter (was 4.0)
                    
                    // Helper macro for vertex
                    #define ADD_VERT(px, py, pz, nx, ny, nz) \
                        mesh_clouds.vertices[v_idx*3+0] = px; \
                        mesh_clouds.vertices[v_idx*3+1] = py; \
                        mesh_clouds.vertices[v_idx*3+2] = pz; \
                        mesh_clouds.normals[v_idx*3+0] = nx; \
                        mesh_clouds.normals[v_idx*3+1] = ny; \
                        mesh_clouds.normals[v_idx*3+2] = nz; \
                        mesh_clouds.texcoords[v_idx*2+0] = 0.0f; \
                        mesh_clouds.texcoords[v_idx*2+1] = 0.0f; \
                        v_idx++;
                    
                    float x1 = cx; float x2 = cx + size;
                    float y1 = cy; float y2 = cy + height;
                    float z1 = cz; float z2 = cz + size;
                    
                    // Top
                    ADD_VERT(x1, y2, z1, 0,1,0); ADD_VERT(x1, y2, z2, 0,1,0); ADD_VERT(x2, y2, z2, 0,1,0); ADD_VERT(x2, y2, z1, 0,1,0);
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+1; mesh_clouds.indices[i_idx++] = idx_offset+2;
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+2; mesh_clouds.indices[i_idx++] = idx_offset+3;
                    idx_offset += 4;
                    
                    // Bottom
                    ADD_VERT(x1, y1, z2, 0,-1,0); ADD_VERT(x1, y1, z1, 0,-1,0); ADD_VERT(x2, y1, z1, 0,-1,0); ADD_VERT(x2, y1, z2, 0,-1,0);
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+1; mesh_clouds.indices[i_idx++] = idx_offset+2;
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+2; mesh_clouds.indices[i_idx++] = idx_offset+3;
                    idx_offset += 4;
                    
                    // Front (Z-)
                    ADD_VERT(x1, y1, z1, 0,0,-1); ADD_VERT(x1, y2, z1, 0,0,-1); ADD_VERT(x2, y2, z1, 0,0,-1); ADD_VERT(x2, y1, z1, 0,0,-1);
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+1; mesh_clouds.indices[i_idx++] = idx_offset+2;
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+2; mesh_clouds.indices[i_idx++] = idx_offset+3;
                    idx_offset += 4;
                    
                    // Back (Z+)
                    ADD_VERT(x1, y1, z2, 0,0,1); ADD_VERT(x2, y1, z2, 0,0,1); ADD_VERT(x2, y2, z2, 0,0,1); ADD_VERT(x1, y2, z2, 0,0,1);
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+1; mesh_clouds.indices[i_idx++] = idx_offset+2;
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+2; mesh_clouds.indices[i_idx++] = idx_offset+3;
                    idx_offset += 4;
                    
                    // Left (X-)
                    ADD_VERT(x1, y1, z2, -1,0,0); ADD_VERT(x1, y2, z2, -1,0,0); ADD_VERT(x1, y2, z1, -1,0,0); ADD_VERT(x1, y1, z1, -1,0,0);
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+1; mesh_clouds.indices[i_idx++] = idx_offset+2;
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+2; mesh_clouds.indices[i_idx++] = idx_offset+3;
                    idx_offset += 4;

                    // Right (X+)
                    ADD_VERT(x2, y1, z1, 1,0,0); ADD_VERT(x2, y2, z1, 1,0,0); ADD_VERT(x2, y2, z2, 1,0,0); ADD_VERT(x2, y1, z2, 1,0,0);
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+1; mesh_clouds.indices[i_idx++] = idx_offset+2;
                    mesh_clouds.indices[i_idx++] = idx_offset+0; mesh_clouds.indices[i_idx++] = idx_offset+2; mesh_clouds.indices[i_idx++] = idx_offset+3;
                    idx_offset += 4;
                    
                    #undef ADD_VERT
                }
            }
        }
        
        UnloadImageColors(pixels);
        UnloadImage(noise);
        
        UploadMesh(&mesh_clouds, false);
        cloud_mesh_built = 1;
    
    }
}

void draw_sky(Camera3D camera, float day_time)
{
    {
BeginMode3D(camera);
    float sun_angle = ((day_time * 2.000000) * 3.141590);
    Vector3 sun_pos = (Vector3){.x = (camera.position.x + (((float)(cos(sun_angle))) * 400.000000)), .y = (camera.position.y + (((float)(sin(sun_angle))) * 400.000000)), .z = camera.position.z};
    Vector3 moon_pos = (Vector3){.x = (camera.position.x - (((float)(cos(sun_angle))) * 400.000000)), .y = (camera.position.y - (((float)(sin(sun_angle))) * 400.000000)), .z = camera.position.z};
    
            rlDisableDepthMask();
            DrawBillboard(camera, tex_sun, sun_pos, 50.0f, WHITE);
            DrawBillboard(camera, tex_moon, moon_pos, 40.0f, WHITE);
            rlEnableDepthMask();
        
EndMode3D();
    }
}

void update_day_night_cycle(float day_time)
{
    {
    float angle = ((day_time * 2.000000) * 3.141590);
    float sun_y = ((float)(sin(angle)));
    float sun_x = ((float)(cos(angle)));
    Vector3 dir = (Vector3){.x = sun_x, .y = sun_y, .z = 0.200000};
    Vector3 col = (Vector3){.x = 1.000000, .y = 1.000000, .z = 1.000000};
    Vector3 amb = (Vector3){.x = 0.001000, .y = 0.001000, .z = 0.001000};
if ((day_time < 0.166000))     {
    float t = (day_time / 0.166000);
(col.x = 1.000000);
(col.y = (0.400000 + (t * 0.600000)));
(col.z = (0.200000 + (t * 0.800000)));
(amb.x = (0.001000 + (t * 0.400000)));
(amb.y = (0.001000 + (t * 0.400000)));
(amb.z = (0.002000 + (t * 0.400000)));
    }
 else if ((day_time < 0.500000))     {
(col = (Vector3){.x = 1.000000, .y = 1.000000, .z = 1.000000});
(amb = (Vector3){.x = 0.400000, .y = 0.400000, .z = 0.400000});
    }
 else if ((day_time < 0.666000))     {
    float t = ((day_time - 0.500000) / 0.166000);
(col.x = (1.000000 - (t * 0.950000)));
(col.y = (1.000000 - (t * 0.950000)));
(col.z = (1.000000 - (t * 0.900000)));
(amb.x = (0.400000 - (t * 0.399000)));
(amb.y = (0.400000 - (t * 0.399000)));
(amb.z = (0.400000 - (t * 0.398000)));
    }
 else     {
(col = (Vector3){.x = 0.050000, .y = 0.050000, .z = 0.100000});
(amb = (Vector3){.x = 0.001000, .y = 0.001000, .z = 0.002000});
    }
update_lighting_uniforms(dir, col, amb);
    }
}

