void Player__update(Player* self, Chunk* chunks, int num_chunks, float dt)
{
    {
    ZC_AUTO mouse_delta = GetMouseDelta();
(self->yaw = (self->yaw + (mouse_delta.x * 0.003000)));
(self->pitch = (self->pitch + (mouse_delta.y * 0.003000)));
if ((self->pitch > 1.500000))     {
(self->pitch = 1.500000);
    }
if ((self->pitch < (-1.500000)))     {
(self->pitch = (-1.500000));
    }
    int cx = ((int)(floor((self->x / 16.000000))));
    int cz = ((int)(floor((self->z / 16.000000))));
    int idx = get_chunk_index(cx, cz);
if ((((chunks[idx].x == cx) && (chunks[idx].z == cz)) && (chunks[idx].light[_z_check_bounds(0, 16)][_z_check_bounds(0, 128)][_z_check_bounds(0, 16)] != (-1))))     {
    double dx = 0.000000;
    double dz = 0.000000;
if (IsKeyDown(KEY_W))     {
(dx = (dx + 1.000000));
    }
if (IsKeyDown(KEY_S))     {
(dx = (dx - 1.000000));
    }
if (IsKeyDown(KEY_A))     {
(dz = (dz - 1.000000));
    }
if (IsKeyDown(KEY_D))     {
(dz = (dz + 1.000000));
    }
    ZC_AUTO fx = cos(self->yaw);
    ZC_AUTO fz = sin(self->yaw);
    ZC_AUTO rx = (-sin(self->yaw));
    ZC_AUTO rz = cos(self->yaw);
    double move_x = ((fx * dx) + (rx * dz));
    double move_z = ((fz * dx) + (rz * dz));
    int player_block = get_block(chunks, num_chunks, ((int)(floor(self->x))), ((int)(floor((self->y + 0.900000)))), ((int)(floor(self->z))));
    int in_water = (player_block == 8);
    double speed_mult = 1.000000;
if (in_water)     {
(speed_mult = 0.500000);
    }
    ZC_AUTO mlen = sqrt(((move_x * move_x) + (move_z * move_z)));
if ((mlen > 0.001000))     {
(move_x = (move_x / mlen));
(move_z = (move_z / mlen));
(self->vx = ((move_x * MOVE_SPEED) * speed_mult));
(self->vz = ((move_z * MOVE_SPEED) * speed_mult));
    }
 else     {
(self->vx = 0.000000);
(self->vz = 0.000000);
    }
    double gravity_mult = 1.000000;
if (in_water)     {
(gravity_mult = 0.300000);
    }
(self->vy = (self->vy - ((((float)(GRAVITY)) * dt) * gravity_mult)));
if (IsKeyPressed(KEY_SPACE))     {
if (check_collision(chunks, num_chunks, self->x, (self->y - 0.100000), self->z, 0.600000, 1.800000))     {
(self->vy = JUMP_FORCE);
    }
    }
    double box_w = 0.600000;
    double box_h = 1.800000;
(self->x = (self->x + (self->vx * dt)));
if (check_collision(chunks, num_chunks, self->x, self->y, self->z, box_w, box_h))     {
(self->x = (self->x - (self->vx * dt)));
(self->vx = 0.000000);
    }
(self->z = (self->z + (self->vz * dt)));
if (check_collision(chunks, num_chunks, self->x, self->y, self->z, box_w, box_h))     {
(self->z = (self->z - (self->vz * dt)));
(self->vz = 0.000000);
    }
(self->y = (self->y + (self->vy * dt)));
if (check_collision(chunks, num_chunks, self->x, self->y, self->z, box_w, box_h))     {
(self->y = (self->y - (self->vy * dt)));
(self->vy = 0.000000);
    }
if ((self->y < (-30.000000)))     {
(self->y = (((float)(CHUNK_HEIGHT)) + 20.000000));
(self->vy = 0.000000);
    }
    }
 else     {
(self->vx = 0.000000);
(self->vy = 0.000000);
(self->vz = 0.000000);
    }
    ZC_AUTO view_x = (cos(self->yaw) * cos(self->pitch));
    ZC_AUTO view_z = (sin(self->yaw) * cos(self->pitch));
    ZC_AUTO view_y = (-sin(self->pitch));
(self->camera.position.x = self->x);
(self->camera.position.y = (self->y + 1.600000));
(self->camera.position.z = self->z);
(self->camera.target.x = (self->camera.position.x + view_x));
(self->camera.target.y = (self->camera.position.y + view_y));
(self->camera.target.z = (self->camera.position.z + view_z));
    }
}

void Chunk__generate_tree(Chunk* self, int x, int y, int z)
{
    {
    int height = 5;
for (ZC_AUTO i = 0; i < height; i++)     {
if (((y + i) < 32))     {
(self->blocks[_z_check_bounds(x, 16)][_z_check_bounds((y + i), 128)][_z_check_bounds(z, 16)] = 5);
    }
    }
    int lh = ((y + height) - 2);
if ((lh < 16))     {
for (ZC_AUTO lx = (-2); lx < 3; lx++)     {
for (ZC_AUTO lz = (-2); lz < 3; lz++)     {
if (((abs(lx) == 2) && (abs(lz) == 2)))     {
continue;
    }
    int tx = (x + lx);
    int tz = (z + lz);
if (((((tx >= 0) && (tx < 16)) && (tz >= 0)) && (tz < 16)))     {
if ((self->blocks[_z_check_bounds(tx, 16)][_z_check_bounds(lh, 128)][_z_check_bounds(tz, 16)] == 0))     {
(self->blocks[_z_check_bounds(tx, 16)][_z_check_bounds(lh, 128)][_z_check_bounds(tz, 16)] = 6);
    }
    }
    }
    }
    }
(lh = ((y + height) - 1));
if ((lh < 16))     {
for (ZC_AUTO lx = (-1); lx < 2; lx++)     {
for (ZC_AUTO lz = (-1); lz < 2; lz++)     {
    int rnd = 0;
     rnd = rand() % 2; 
if ((((abs(lx) == 1) && (abs(lz) == 1)) && (rnd == 0)))     {
continue;
    }
    int tx = (x + lx);
    int tz = (z + lz);
if (((((tx >= 0) && (tx < 16)) && (tz >= 0)) && (tz < 16)))     {
if ((self->blocks[_z_check_bounds(tx, 16)][_z_check_bounds(lh, 128)][_z_check_bounds(tz, 16)] == 0))     {
(self->blocks[_z_check_bounds(tx, 16)][_z_check_bounds(lh, 128)][_z_check_bounds(tz, 16)] = 6);
    }
    }
    }
    }
    }
(lh = (y + height));
if ((lh < 16))     {
if ((self->blocks[_z_check_bounds(x, 16)][_z_check_bounds(lh, 128)][_z_check_bounds(z, 16)] == 0))     {
(self->blocks[_z_check_bounds(x, 16)][_z_check_bounds(lh, 128)][_z_check_bounds(z, 16)] = 6);
    }
if (((x + 1) < 16))     {
(self->blocks[_z_check_bounds((x + 1), 16)][_z_check_bounds(lh, 128)][_z_check_bounds(z, 16)] = 6);
    }
if (((x - 1) >= 0))     {
(self->blocks[_z_check_bounds((x - 1), 16)][_z_check_bounds(lh, 128)][_z_check_bounds(z, 16)] = 6);
    }
if (((z + 1) < 16))     {
(self->blocks[_z_check_bounds(x, 16)][_z_check_bounds(lh, 128)][_z_check_bounds((z + 1), 16)] = 6);
    }
if (((z - 1) >= 0))     {
(self->blocks[_z_check_bounds(x, 16)][_z_check_bounds(lh, 128)][_z_check_bounds((z - 1), 16)] = 6);
    }
    }
    }
}

Chunk Chunk__new(int x, int z)
{
    {
    Chunk c = {0};
(c.x = x);
(c.z = z);
(c.mesh_dirty = 1);
(c.mesh_built = 0);
(c.water_mesh_built = 0);
(c.plant_mesh_built = 0);
(c.grass_deco_built = 0);
(c.locked = 0);
(c.plant_count = 0);
memset((&c.chunk_model), 0, sizeof(Model));
memset((&c.water_model), 0, sizeof(Model));
memset((&c.plant_model), 0, sizeof(Model));
memset((&c.grass_deco_model), 0, sizeof(Model));
    int heights[16][16] = {0};
    
            Image noise = GenImagePerlinNoise(16, 16, x * 16, z * 16, 0.5f);

            // Use LoadImageColors to safely get pixel data regardless of format
            Color* pixels = LoadImageColors(noise);

            for (int i = 0; i < 16; i++) {
                for (int j = 0; j < 16; j++) {
                    // pixels is row-major: y * width + x
                    // we want x=i, z=j. z is y in image.
                    Color col = pixels[j * 16 + i];
                    int val = col.r; // Grayscale, so r=g=b

                    // Map 0..255 to height 4..130 (More verticality)
                    int h = 4 + (val / 2);
                    if (h > CHUNK_HEIGHT - 10) h = CHUNK_HEIGHT - 10;
                    heights[i][j] = h;
                }
            }
            UnloadImageColors(pixels);
            UnloadImage(noise);
        
    #define SEA_LEVEL_GEN 30

for (ZC_AUTO cx = 0; cx < 16; cx++)     {
for (ZC_AUTO cz = 0; cz < 16; cz++)     {
    int h = heights[_z_check_bounds(cx, 16)][_z_check_bounds(cz, 16)];
for (ZC_AUTO cy = 0; cy < CHUNK_HEIGHT; cy++)     {
    int l = 0;
if ((cy < (h - 1)))     {
(c.blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 3);
    }
 else if ((cy < h))     {
(c.blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 1);
    }
 else if ((cy == h))     {
if ((h < SEA_LEVEL_GEN))     {
(c.blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 9);
    }
 else     {
(c.blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 2);
    }
(l = 15);
    }
 else     {
(c.blocks[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = 0);
(l = 15);
    }
(c.light[_z_check_bounds(cx, 16)][_z_check_bounds(cy, 128)][_z_check_bounds(cz, 16)] = l);
    }
    }
    }
    
            #define SEA_LEVEL 30
            for (int wx = 0; wx < 16; wx++) {
                for (int wz = 0; wz < 16; wz++) {
                    for (int wy = 0; wy < SEA_LEVEL; wy++) {
                        if (c.blocks[wx][wy][wz] == BLOCK_AIR) {
                            c.blocks[wx][wy][wz] = BLOCK_WATER;
                        }
                    }
                }
            }
            #undef SEA_LEVEL
        
(c.plant_count = 0);
    
            // Use chunk coordinates as seed for consistent randomness
            srand(x * 73856093 ^ z * 19349663);
            
            #define SEA_LEVEL_VEG 30
            for (int cx = 0; cx < 16; cx++) {
                for (int cz = 0; cz < 16; cz++) {
                    int h = heights[cx][cz];
                    
                    // Skip vegetation for underwater surfaces
                    if (h < SEA_LEVEL_VEG) continue;
                    
                    // Check if surface is grass
                    if (c.blocks[cx][h][cz] == BLOCK_GRASS && h < CHUNK_HEIGHT - 1) {
                        int r = rand() % 100;
                        
                        // 10% chance for Tree
                        if (r < 10) {
                            // Generate Tree
                            // Needs space?
                            if (cx > 1 && cx < 14 && cz > 1 && cz < 14) {
                                // Simple bounds check to avoid cross-chunk complexity for now
                                // (Ideally would handle cross-chunk)
                                // We need to cast 'c' to 'Chunk*' or call method differently?
                                // self logic... 'c' is local.
                                // We can't call method on local struct effectively if it expects pointer.
                                // But generate_tree takes 'self' (by value copy? No, implicit ptr usually? Structs are value types in C)
                                // In Zen-C methods on struct take 'self' which effectively acts on the instance.
                                // But 'c' is being built.
                                
                                // Let's inline or use helper that takes pointer
                                // Calling generated method: Chunk_generate_tree(&c, ...)
                                
                                // Actually, I can just call it if I change 'self' to 'Chunk*' or use (&c).generate_tree(...)
                                // Let's try: (&c).generate_tree(...)
                                
                                // Wait, c is a local struct, not pointer.
                                // I'll just manually inline the logic or use a static helper.
                                // Actually, I defined `generate_tree(self...` above.
                                // So I should be able to call `c.generate_tree(...)` if self is value, or `(&c).generate_tree` if self is ref.
                                // Given `fn draw(self...)`, it seems self is value or implicit ref.
                                // Let's assume `(&c).generate_tree(...)` works if I added it as a method.
                                
                                // IMPORTANT: I cannot add a method inside `impl Chunk` via replace_content easily if I don't see the top of `impl`.
                                // I AM inside impl Chunk (replacing `new`).
                                // Wait, `new` is `static fn`. `generate_tree` is instance `fn`.
                                // I will add `generate_tree` BEFORE `new` inside `impl Chunk`.
                                // My replacement content STARTS with `fn generate_tree`.
                                // And I am replacing `static fn new` block.
                                // So I am inserting `generate_tree` before `new` and replacing `new`.
                                // This assumes I am replacing from line 256. 
                                
                                // Correct invocation:
                                // (&c).generate_tree(cx, h + 1, cz);
                                // However, generate_tree modifies `self`. If `self` is passed by value, `c` won't change.
                                // Zen-C structs are pass-by-value unless `*`.
                                // `fn generate_tree(self...` -> `self` is `Chunk`. modifying `self.blocks` modifies copy.
                                // I must use `Chunk* self`? No, Zen-C syntax `fn method(self)` usually implies context.
                                // If I want to modify, I probably need `fn generate_tree(self: Chunk* ...)`? 
                                // Or `fn generate_tree(self ...)` and call it on `&c`.
                                // Let's check `draw(self)` -> it calls `build_chunk_mesh(self...)`. 
                                // But `build_chunk_mesh` takes `Chunk*`. 
                                // `self` in `draw` IS `Chunk*`? 
                                // `fn draw(self)` usually means `self` is `Chunk` (value) or `Chunk*` (ptr).
                                // In `c.draw()`, `c` is `Chunk*` in main.zc loop.
                                // Here `c` is `Chunk` (stack).
                                // I will manually implement tree logic inline to avoid method issues.
                                
                                // Tree Logic Inline
                                int tree_h = 5;
                                for(int k=0; k<tree_h; k++) {
                                    if(h+1+k < CHUNK_HEIGHT) c.blocks[cx][h+1+k][cz] = BLOCK_LOG;
                                }
                                // Leaves ... simplified
                                int ly = h + 1 + tree_h - 2;
                                for(int ly_off = 0; ly_off < 2; ly_off++) {
                                    int chy = ly + ly_off;
                                    if(chy < CHUNK_HEIGHT) {
                                        for(int lx=-2; lx<=2; lx++) {
                                            for(int lz=-2; lz<=2; lz++) {
                                                if(abs(lx)==2 && abs(lz)==2) continue;
                                                int tx = cx + lx;
                                                int tz = cz + lz;
                                                if(tx>=0 && tx<16 && tz>=0 && tz<16) {
                                                    if(c.blocks[tx][chy][tz] == BLOCK_AIR) {
                                                        c.blocks[tx][chy][tz] = BLOCK_LEAVES;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                // Top
                                int th = h + 1 + tree_h;
                                if(th < CHUNK_HEIGHT) {
                                     c.blocks[cx][th][cz] = BLOCK_LEAVES;
                                     if(cx+1<16) c.blocks[cx+1][th][cz] = BLOCK_LEAVES;
                                     if(cx-1>=0) c.blocks[cx-1][th][cz] = BLOCK_LEAVES;
                                     if(cz+1<16) c.blocks[cx][th][cz+1] = BLOCK_LEAVES;
                                     if(cz-1>=0) c.blocks[cx][th][cz-1] = BLOCK_LEAVES;
                                }
                            }
                        }
                        
                        // 20% chance for Grass (re-check generated tree didn't overwrite)
                        else if (r < 20) {
                             if (c.blocks[cx][h+1][cz] == BLOCK_AIR && c.plant_count < 64) {
                                c.plants[c.plant_count].x = (float)cx + 0.5f;
                                c.plants[c.plant_count].y = (float)(h + 1);
                                c.plants[c.plant_count].z = (float)cz + 0.5f;
                                c.plants[c.plant_count].plant_type = BLOCK_TALLGRASS; 
                                c.plant_count++;
                             }
                        }
                    }
                }
            }
        
(c.mesh_dirty = 1);
(c.mesh_built = 0);
    return c;
    }
}

void Chunk__draw_opaque(Chunk* self, Chunk* chunks, int num_chunks, int* builds_in_frame, int max_builds, int player_cx, int player_cz)
{
    {
if ((self->x == (-9999)))     {
    return ;
    }
if (self->mesh_built)     {
    float gx_base = ((float)((self->x * 16)));
    float gz_base = ((float)((self->z * 16)));
    Vector3 offset = (Vector3){.x = gx_base, .y = 0.000000, .z = gz_base};
DrawModel(self->chunk_model, offset, 1.000000, WHITE);
    }
    }
}

void Chunk__draw_transparent(Chunk* self, Chunk* chunks, int num_chunks, int player_cx, int player_cz, float grass_dist)
{
    {
if ((self->x == (-9999)))     {
    return ;
    }
    float gx_base = ((float)((self->x * 16)));
    float gz_base = ((float)((self->z * 16)));
    Vector3 offset = (Vector3){.x = gx_base, .y = 0.000000, .z = gz_base};
if (self->water_mesh_built)     {
DrawModel(self->water_model, offset, 1.000000, WHITE);
    }
if ((self->plant_mesh_built != 0))     {
DrawModel(self->plant_model, offset, 1.000000, WHITE);
    }
if ((grass_dist > 0.000000))     {
    float dx = (((float)(player_cx)) - (gx_base + 8.000000));
    float dz = (((float)(player_cz)) - (gz_base + 8.000000));
    float dist_sq = ((dx * dx) + (dz * dz));
    float dist_thresh = (grass_dist * grass_dist);
if ((dist_sq < dist_thresh))     {
if (((self->grass_deco_built == 0) && (self->mesh_built != 0)))     {
build_grass_decorations(self, chunks, num_chunks);
    }
if ((self->grass_deco_built != 0))     {
DrawModel(self->grass_deco_model, offset, 1.000000, WHITE);
    }
    }
    }
    }
}
